#include <bits/stdc++.h>
using namespace std;

class ERockPaperScissors {
public:
    int minDiff;

    void evaluate(vector<vector<int>> &pairs, vector<int> a, vector<int> b) {
        for (auto &p : pairs) {
            int m = min(a[p[0]], b[p[1]]);
            b[p[1]] -= m;
            a[p[0]] -= m;
        }
        int total = 0;
        for (int val : a) total += val;
        minDiff = min(minDiff, total);
    }

    void generatePermutations(vector<vector<int>> &pairs, int start, vector<int> a, vector<int> b) {
        evaluate(pairs, a, b);
        for (int i = start; i < (int)pairs.size(); i++) {
            swap(pairs[start], pairs[i]);
            generatePermutations(pairs, start + 1, a, b);
            swap(pairs[start], pairs[i]);
        }
    }

    void play(istream &in, ostream &out) {
        int n;
        in >> n;
        vector<int> a(3), b(3);
        minDiff = INT_MAX;
        vector<string> aStr(3), bStr(3);
        for (int i = 0; i < 3; i++) {
            in >> aStr[i];
        }
        for (int i = 0; i < 3; i++) {
            in >> bStr[i];
        }
        for (int i = 0; i < 3; i++) {
            a[i] = stoi(aStr[i]);
            b[i] = stoi(bStr[i]);
        }
        int maxScore = min(a[0], b[1]) + min(a[1], b[2]) + min(a[2], b[0]);
        vector<vector<int>> pairs = {
            {0, 0},
            {1, 1},
            {2, 2},
            {0, 2},
            {1, 0},
            {2, 1}
        };
        generatePermutations(pairs, 0, a, b);
        out << minDiff << " " << maxScore << "\n";
    }
};

int main() {
    ERockPaperScissors game;
    game.play(cin, cout);
    return 0;
}

